	get(employer, 'entity_extension_data.minimum_wage_400_business', false)
		? ctx.lookup.minimum_wage.business_400
		: get(ctx.lookup.minimum_wage, 'by_region.' + String(get(employer, 'entity_extension_data.region', '')), 0);
