	Object.values(get(terms, 'allowances', {}))
		.filter((allowance) => get(allowance, 'fixed', true) !== false)
		.map((allowance) => get(allowance, 'amount', 0))
);
const paid =
	rate.unit === 'DAILY'
		? rate.amount
		: rate.unit === 'HOURLY'
			? rate.amount * get(terms, 'normal_hours_per_day', ctx.lookup.hours_per_day)
			: (get(rate, 'amount', 0) + fixed) / ctx.lookup.calendar_days;
return Math.max(0, minimum - paid) * ctx.entry.quantity;

