const terms = get(ctx.subject.employment, 'terms', {});
const rate = get(terms, 'rate', {});
const hours = get(
	terms,
	'normal_hours_per_day',
	get(terms, 'statutory_work_category', null) === 'HAZARDOUS'
		? ctx.lookup.hazardous_hours_per_day
		: ctx.lookup.hours_per_day
);
// A monthly wage takes the fixed allowance paid for normal work (LPA ss.5, 68).
const allowance = Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0));
const hourly =
	rate.unit === 'HOURLY'
		? rate.amount
		: rate.unit === 'DAILY'
			? rate.amount / hours
			: (get(rate, 'amount', 0) + allowance) / ctx.lookup.calendar_days / hours;
return hourly * ctx.entry.quantity;

